import Foundation
import XCTest

@testable import RedScreenCore

/// RED-13: the Swift protocol reproduces the extension's vectors byte for byte
/// (Extensions/vscode/test/fixtures/protocol-vectors.json, generated by the TypeScript code).
final class HintProtocolVectorTests: XCTestCase {
    private var vectors: [String: Any] = [:]

    override func setUpWithError() throws {
        let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        let data = try Data(contentsOf: root.appendingPathComponent("Extensions/vscode/test/fixtures/protocol-vectors.json"))
        vectors = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
    }

    private func bytes(_ value: Any?, _ length: Int) throws -> Data {
        try HintProtocol.decodeBase64url(value, length: length)
    }

    private var inputs: (key: Data, session: Data, client: Data, server: Data) {
        get throws {
            let inputs = try XCTUnwrap(vectors["inputs"] as? [String: Any])
            return (try bytes(inputs["key"], 32), try bytes(inputs["session"], 16),
                    try bytes(inputs["clientNonce"], 16), try bytes(inputs["serverNonce"], 16))
        }
    }

    func testProofsAndKeysMatch() throws {
        let (key, session, client, server) = try inputs
        XCTAssertEqual(HintProtocol.base64url(HintProtocol.serverProof(key: key, session: session, clientNonce: client, serverNonce: server)),
                       vectors["serverProof"] as? String)
        XCTAssertEqual(HintProtocol.base64url(HintProtocol.clientProof(key: key, session: session, clientNonce: client, serverNonce: server)),
                       vectors["clientProof"] as? String)
        XCTAssertEqual(HintProtocol.base64url(HintProtocol.connectionKey(
            key: key, session: session, clientNonce: client, serverNonce: server, direction: .clientToServer)),
                       vectors["clientToServerKey"] as? String)
        XCTAssertEqual(HintProtocol.base64url(HintProtocol.connectionKey(
            key: key, session: session, clientNonce: client, serverNonce: server, direction: .serverToClient)),
                       vectors["serverToClientKey"] as? String)
        XCTAssertEqual(HintProtocol.base64url(HintProtocol.digestKey(key: key, session: session)), vectors["digestKey"] as? String)
    }

    func testNormalizationAndDigestsMatch() throws {
        let digestKey = try bytes(vectors["digestKey"], 32)
        let cases = try XCTUnwrap(vectors["digests"] as? [[String: String]])
        XCTAssertGreaterThanOrEqual(cases.count, 8)
        for testCase in cases {
            let value = try XCTUnwrap(testCase["value"])
            let rule = try XCTUnwrap(testCase["rule"])
            XCTAssertEqual(HintProtocol.normalize(value), testCase["normalized"], rule)
            XCTAssertEqual(HintProtocol.base64url(HintProtocol.digest(digestKey: digestKey, rule: rule, value: value)),
                           testCase["digest"], rule)
        }
    }

    func testCanonicalJSONMatches() throws {
        for entry in try XCTUnwrap(vectors["canonical"] as? [[String: Any]]) {
            XCTAssertEqual(try HintProtocol.canonicalJSON(entry["value"]), entry["json"] as? String)
        }
    }

    func testExtensionFramesVerifyAndNativeTagsMatch() throws {
        let frames = try XCTUnwrap(vectors["frames"] as? [String: [String: String]])
        let clientToServer = try bytes(vectors["clientToServerKey"], 32)
        let serverToClient = try bytes(vectors["serverToClientKey"], 32)

        // A hints frame the extension sealed verifies here and validates while fresh.
        let hintsFrame = Data(try XCTUnwrap(frames["hints"]?["json"]).utf8)
        let message = try HintProtocol.parseFrame(hintsFrame, expected: ["hints"])
        let body = try HintProtocol.verifyTag(key: clientToServer, message: message)
        let sent = try HintProtocol.integer(body["sent"])
        let validated = try HintProtocol.validateHints(body, now: sent + 1_000)
        XCTAssertEqual(validated.hints.count, 1)
        let digests = try XCTUnwrap(vectors["digests"] as? [[String: String]])
        XCTAssertEqual(HintProtocol.base64url(validated.hints[0].digest), digests[0]["digest"])
        XCTAssertThrowsError(try HintProtocol.verifyTag(key: serverToClient, message: message))
        XCTAssertThrowsError(try HintProtocol.validateHints(body, now: sent + 30_001)) {
            XCTAssertEqual($0 as? HintProtocolError, .expired)
        }

        // Frames this side seals carry the same tags the extension computes.
        for name in ["ready", "ack"] {
            let frame = Data(try XCTUnwrap(frames[name]?["json"]).utf8)
            var expectedBody = try XCTUnwrap(JSONSerialization.jsonObject(with: frame) as? [String: Any])
            let tag = expectedBody.removeValue(forKey: "mac") as? String
            XCTAssertEqual(tag, frames[name]?["tag"])
            XCTAssertEqual(HintProtocol.base64url(try HintProtocol.tag(key: serverToClient, body: expectedBody)), tag, name)
        }
    }

    func testTamperedFramesFailClosed() throws {
        let frames = try XCTUnwrap(vectors["frames"] as? [String: [String: String]])
        let clientToServer = try bytes(vectors["clientToServerKey"], 32)
        let json = try XCTUnwrap(frames["hints"]?["json"])
        var message = try HintProtocol.parseFrame(Data(json.utf8), expected: ["hints"])
        message["seq"] = 4
        XCTAssertThrowsError(try HintProtocol.verifyTag(key: clientToServer, message: message)) {
            XCTAssertEqual($0 as? HintProtocolError, .authenticationFailed)
        }
    }

    func testMalformedMessagesAreRejected() {
        func reason(_ text: String, expected: Set<String> = ["hello", "hints"]) -> HintProtocolError? {
            do {
                _ = try HintProtocol.parseFrame(Data(text.utf8), expected: expected)
                return nil
            } catch {
                return error as? HintProtocolError
            }
        }
        XCTAssertEqual(reason(#"{"t":"hello","v":2,"session":"a","nonce":"b"}"#), .incompatibleVersion)
        XCTAssertEqual(reason(#"{"t":"hello","v":true,"session":"a","nonce":"b"}"#), .malformedMessage)
        XCTAssertEqual(reason(#"{"t":"hello","v":"1","session":"a","nonce":"b"}"#), .malformedMessage)
        XCTAssertEqual(reason(#"{"t":"hello","v":1,"session":"a","nonce":"b","extra":1}"#), .malformedMessage)
        XCTAssertEqual(reason(#"{"t":"ready","v":1,"seq":0,"mac":"x"}"#), .unexpectedMessage)
        XCTAssertEqual(reason("not json"), .malformedMessage)
        XCTAssertEqual(reason("[]"), .malformedMessage)
        XCTAssertEqual(reason(String(repeating: " ", count: HintProtocol.maximumFrameBytes + 1)), .oversizedMessage)

        let now: Int64 = 1_767_225_600_000
        func hints(_ entries: [Any], sent: Int64 = now, expires: Int64 = now + 10_000) -> [String: Any] {
            ["t": "hints", "v": 1, "seq": 0, "sent": sent, "expires": expires,
             "doc": HintProtocol.base64url(Data(repeating: 7, count: 16)), "hints": entries]
        }
        let digest = HintProtocol.base64url(Data(repeating: 1, count: 32))
        let good: [String: Any] = ["rule": "assignment.env", "conf": 90, "digest": digest]
        XCTAssertEqual(try HintProtocol.validateHints(hints([good]), now: now).hints.count, 1)
        let bad: [[String: Any]] = [
            good.merging(["rule": "made.up"]) { $1 },
            good.merging(["conf": 101]) { $1 },
            good.merging(["conf": 0.5]) { $1 },
            good.merging(["digest": "short"]) { $1 },
            good.merging(["value": "RSFAKE-must-never-be-accepted"]) { $1 },
        ]
        for entry in bad {
            XCTAssertThrowsError(try HintProtocol.validateHints(hints([entry]), now: now))
        }
        XCTAssertThrowsError(try HintProtocol.validateHints(hints(Array(repeating: good, count: 65)), now: now))
        XCTAssertThrowsError(try HintProtocol.validateHints(hints([good], expires: now + 30_001), now: now))
        XCTAssertThrowsError(try HintProtocol.validateHints(hints([good], sent: now + 5_000, expires: now + 6_000), now: now)) {
            XCTAssertEqual($0 as? HintProtocolError, .expired)
        }
    }

    func testSequenceGuardAndFrameDecoder() throws {
        var sequence = HintSequenceGuard()
        try sequence.accept(0)
        try sequence.accept(1)
        XCTAssertThrowsError(try sequence.accept(1))
        XCTAssertThrowsError(try sequence.accept(3))

        var decoder = HintFrameDecoder()
        let stream = try HintFrameDecoder.encode(Data("{\"a\":1}".utf8)) + HintFrameDecoder.encode(Data("{\"b\":2}".utf8))
        XCTAssertEqual(try decoder.push(stream.prefix(3)), [])
        XCTAssertEqual(try decoder.push(stream.dropFirst(3)).map { String(decoding: $0, as: UTF8.self) }, ["{\"a\":1}", "{\"b\":2}"])
        var oversized = HintFrameDecoder()
        XCTAssertThrowsError(try oversized.push(Data([0, 0, 0x40, 0x01]))) {
            XCTAssertEqual($0 as? HintProtocolError, .oversizedMessage)
        }
    }

    /// The extension's rule list and the native protocol's are the same set.
    func testRuleListsMatchTheExtension() throws {
        let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        let source = try String(contentsOf: root.appendingPathComponent("Extensions/vscode/src/rules.ts"), encoding: .utf8)
        let start = try XCTUnwrap(source.range(of: "export const RULE_IDS = ["))
        let end = try XCTUnwrap(source.range(of: "] as const", range: start.upperBound..<source.endIndex))
        let ids = source[start.upperBound..<end.lowerBound].split(separator: "'").enumerated()
            .filter { $0.offset % 2 == 1 }.map { String($0.element) }
        XCTAssertEqual(Set(ids), HintProtocol.ruleIDs)
    }
}
